mapper.select:
SELECT

FROM swm_inspection_list a

WHERE a.id = #{id}

SELECT

FROM swm_inspection_list a


    a.status = #{status}

        AND plan.plan_code LIKE concat('%', #{planCode}, '%')


        AND a.plan_name LIKE concat('%', #{planName}, '%')


        AND p.name = #{inspector}


        AND a.inspection_type = #{inspectionType}


        AND a.inspection_list_status = #{inspectionListStatus}


ORDER BY a.update_date DESC

SELECT COUNT(1) 
FROM swm_inspection_list a
WHERE a.status = '0'
AND a.plan_id = #{planId}
AND DATE_FORMAT(a.start_time, '%Y-%m-%d') = #{dateStr}
